function pdfDraw() {
  for (var y = 0; y < 64; y++) pdfDoc.getField("row" + y).value = pdfFrames[pdfFrame][y];
  pdfDoc.getField("status").value = "Frame " + pdfFrame + " / " + (pdfTimer ? "playing" : "paused");
}
function pdfTick() {
  pdfFrame = (pdfFrame + 1) % pdfFrames.length;
  pdfDraw();
}
function pdfCommand(c) {
  c = c.toLowerCase();
  if (c === "p") {
    if (pdfTimer) {
      app.clearInterval(pdfTimer);
      pdfTimer = null;
    } else {
      pdfTimer = app.setInterval("pdfTick()", 125);
    }
    pdfDraw();
  }
  if (c === "n") pdfTick();
  if (c === "r") {
    pdfFrame = 0;
    pdfDraw();
  }
}
pdfDraw();
